def chat_between_agents(user_proxy, assistant, max_turns=10):
    history = []
    message = user_proxy.send()
    history.append({"role": "user", "content": message})
    for turn in range(max_turns):
        response = assistant.reply(message)
        history.append({"role": "assistant", "content": response})
        if "TERMINATE" in response:
            break
        feedback = user_proxy.evaluate(response)
        history.append({"role": "user", "content": feedback})
        if "TERMINATE" in feedback:
            break
        message = feedback
    return {"history": history, "turns": turn + 1}
